import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.166.1/build/three.module.js';

const canvas=document.querySelector('#scene');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,2));
renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.outputColorSpace=THREE.SRGBColorSpace;
renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x171326);scene.fog=new THREE.FogExp2(0x171326,.023);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,180);
scene.add(new THREE.HemisphereLight(0xb7a3d8,0x21182c,2.1));
const moon=new THREE.DirectionalLight(0xe4d6ff,2.1);moon.position.set(-12,20,8);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);moon.shadow.camera.left=-28;moon.shadow.camera.right=28;moon.shadow.camera.top=30;moon.shadow.camera.bottom=-30;scene.add(moon);
const warm=new THREE.PointLight(0xffbb75,28,30,2);warm.position.set(1,5,-23);scene.add(warm);
const groundMat=new THREE.MeshStandardMaterial({color:0x272233,roughness:.96});
const ground=new THREE.Mesh(new THREE.PlaneGeometry(120,150),groundMat);ground.rotation.x=-Math.PI/2;ground.position.set(0,-.12,-26);ground.receiveShadow=true;scene.add(ground);
const pathMat=new THREE.MeshStandardMaterial({color:0x51485b,roughness:.85});
for(let i=0;i<33;i++){const slab=new THREE.Mesh(new THREE.BoxGeometry(5.3,.14,2.05),pathMat);slab.position.set(0,-.02,13-i*2.15);slab.receiveShadow=true;slab.castShadow=true;scene.add(slab);}
const edgeMat=new THREE.MeshStandardMaterial({color:0x463c4d,roughness:1});
for(const x of [-3.15,3.15]){const curb=new THREE.Mesh(new THREE.BoxGeometry(.2,.3,73),edgeMat);curb.position.set(x,.04,-23);curb.receiveShadow=true;scene.add(curb);}
const mats={bark:new THREE.MeshStandardMaterial({color:0x282132,roughness:1}),leaf:new THREE.MeshStandardMaterial({color:0x2d293b,roughness:1}),leaf2:new THREE.MeshStandardMaterial({color:0x40344b,roughness:1}),gold:new THREE.MeshStandardMaterial({color:0xd9b96f,metalness:.55,roughness:.35,emissive:0x69441a,emissiveIntensity:.3}),stone:new THREE.MeshStandardMaterial({color:0x51465d,roughness:.85}),castle:new THREE.MeshStandardMaterial({color:0x494257,roughness:.85}),roof:new THREE.MeshStandardMaterial({color:0x292335,roughness:.82}),glow:new THREE.MeshStandardMaterial({color:0xffd789,emissive:0xffa832,emissiveIntensity:2.6}),
 player:new THREE.MeshStandardMaterial({color:0x465269,roughness:.68}),cloak:new THREE.MeshStandardMaterial({color:0x252a3c,roughness:.9}),skin:new THREE.MeshStandardMaterial({color:0xd4aa83,roughness:.75}),witch:new THREE.MeshStandardMaterial({color:0x49405c,roughness:.8}),zombie:new THREE.MeshStandardMaterial({color:0x59665a,roughness:1}),dark:new THREE.MeshStandardMaterial({color:0x2c2634,roughness:.9}),
};
function mesh(geo,mat,parent,x=0,y=0,z=0){const m=new THREE.Mesh(geo,mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function addTree(x,z,scale=1,variant=0){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(scale);scene.add(g);mesh(new THREE.CylinderGeometry(.24,.48,5,7),mats.bark,g,0,2.5,0);for(let i=0;i<3;i++){const crown=mesh(new THREE.ConeGeometry(1.6-i*.25,3.3,7),i%2?mats.leaf:mats.leaf2,g,0,4.2+i*1.25,0);crown.rotation.y=variant*.8+i;}for(let b=0;b<2;b++){const branch=mesh(new THREE.CylinderGeometry(.09,.17,2.3,6),mats.bark,g,b?-.8:.8,3.4,b?-.4:.35);branch.rotation.z=b?-.68:.68;branch.rotation.x=b?.15:-.2;}return g;}
for(let i=0;i<50;i++){let z=15-(i%25)*2.7,x=(i%2?1:-1)*(5.3+(i%4)*1.8);addTree(x,z,.75+(i%5)*.12,i%3);}
// Floating lanterns and scattered rune stones
for(let i=0;i<13;i++){const side=i%2?1:-1,z=9-i*4.8;const post=mesh(new THREE.CylinderGeometry(.11,.18,1.3,7),mats.stone,scene,side*3.9,.55,z);const lamp=mesh(new THREE.IcosahedronGeometry(.2,1),mats.glow,scene,side*3.9,1.32,z);lamp.scale.set(.8,1.2,.8);const light=new THREE.PointLight(0xffc971,2.8,7,2);light.position.set(side*3.9,1.35,z);scene.add(light);}
// The distant castle and its sealed gate
const castleGroup=new THREE.Group();castleGroup.position.set(0,0,-52);scene.add(castleGroup);
mesh(new THREE.BoxGeometry(12,9,3),mats.castle,castleGroup,0,4.5,0);
mesh(new THREE.BoxGeometry(4.4,6.8,.4),mats.roof,castleGroup,0,4.2,1.72);
function tower(x,z,height=12){const t=mesh(new THREE.CylinderGeometry(1.45,1.75,height,9),mats.castle,castleGroup,x,height/2,z);mesh(new THREE.ConeGeometry(2.05,3.1,9),mats.roof,castleGroup,x,height+1.5,z);for(let k=-1;k<=1;k++){const slit=mesh(new THREE.BoxGeometry(.2,.9,.09),mats.glow,castleGroup,x+k*.55,4.2,z+1.56);slit.material=mats.glow;}}
tower(-5.3,.1,12);tower(5.3,.1,12);tower(-3.9,-1.1,9);tower(3.9,-1.1,9);
const gate=new THREE.Group();castleGroup.add(gate);for(let x=-1.25;x<=1.26;x+=.5)mesh(new THREE.BoxGeometry(.08,3.6,.18),mats.gold,gate,x,1.8,2.2);mesh(new THREE.BoxGeometry(2.7,.1,.18),mats.gold,gate,0,3.55,2.2);mesh(new THREE.TorusGeometry(1.05,.08,8,28,Math.PI),mats.gold,castleGroup,0,3.45,2.18);
const moonDisc=mesh(new THREE.SphereGeometry(3,24,16),new THREE.MeshBasicMaterial({color:0x8c74a5,transparent:true,opacity:.2}),scene,-13,15,-58);moonDisc.scale.set(1,1,.08);
// Player avatar
const player=new THREE.Group();scene.add(player);player.position.set(0,0,8);
mesh(new THREE.ConeGeometry(.63,1.75,7),mats.cloak,player,0,1.05,.04).rotation.x=.12;
mesh(new THREE.SphereGeometry(.37,14,12),mats.skin,player,0,2.05,-.03);
const hood=mesh(new THREE.ConeGeometry(.49,.8,7),mats.cloak,player,0,2.42,-.01);hood.rotation.x=.1;
mesh(new THREE.BoxGeometry(.3,.12,.08),mats.gold,player,0,2.1,.3);
const wand=new THREE.Group();wand.position.set(.49,1.34,-.03);player.add(wand);const wandStick=mesh(new THREE.CylinderGeometry(.035,.055,.92,7),mats.gold,wand,0,.42,0);wandStick.rotation.z=-.42;const wandGem=mesh(new THREE.OctahedronGeometry(.13),mats.glow,wand,.2,.83,0);
const playerAura=new THREE.PointLight(0x9d8bff,1.4,4,2);playerAura.position.set(0,1.7,0);player.add(playerAura);
// Enemies: witches channel wand magic; zombies lumber toward the path.
function makeEnemy(type,x,z,index){const g=new THREE.Group();scene.add(g);g.position.set(x,0,z);const skin=type==='witch'?mats.skin:mats.zombie;const robe=type==='witch'?mats.witch:mats.zombie;
 mesh(new THREE.ConeGeometry(.66,1.75,7),robe,g,0,1.02,0);mesh(new THREE.SphereGeometry(.36,12,10),skin,g,0,2.04,0);
 if(type==='witch'){const hat=mesh(new THREE.ConeGeometry(.48,.95,7),mats.dark,g,0,2.66,0);hat.rotation.z=.12;mesh(new THREE.TorusGeometry(.35,.07,6,12),mats.dark,g,0,2.32,0);const staff=mesh(new THREE.CylinderGeometry(.035,.055,1.2,6),mats.gold,g,.55,1.15,0);staff.rotation.z=-.15;mesh(new THREE.OctahedronGeometry(.17),new THREE.MeshStandardMaterial({color:0xbf75ee,emissive:0x9d42e7,emissiveIntensity:1.6}),g,.58,1.82,0);for(const eyeX of [-.13,.13])mesh(new THREE.SphereGeometry(.045),new THREE.MeshBasicMaterial({color:0xe6a8ff}),g,eyeX,2.07,.31);
 }else{mesh(new THREE.BoxGeometry(.13,.1,.08),new THREE.MeshBasicMaterial({color:0xd8d56b}),g,-.12,2.08,.32);mesh(new THREE.BoxGeometry(.13,.1,.08),new THREE.MeshBasicMaterial({color:0xd8d56b}),g,.12,2.08,.32);const arm=mesh(new THREE.CylinderGeometry(.12,.15,.8,6),skin,g,.58,1.32,0);arm.rotation.z=-.7;}
 const bar=new THREE.Group();bar.position.set(0,3.35,0);g.add(bar);mesh(new THREE.BoxGeometry(1.35,.13,.06),new THREE.MeshBasicMaterial({color:0x19131f}),bar,0,0,0);const fill=mesh(new THREE.BoxGeometry(1.25,.075,.07),new THREE.MeshBasicMaterial({color:type==='witch'?0xcf8be9:0x9bcb83}),bar,0,0,.045);fill.userData.baseWidth=1.25;
 return {group:g,type,hp:100,alive:true,bar,fill,shot:1.2+Math.random()*1.7,baseX:x,baseZ:z,id:index,attackFlash:0};}
const enemies=[makeEnemy('witch',-1.6,-7.8,0),makeEnemy('zombie',1.45,-14,1),makeEnemy('witch',1.65,-21,2),makeEnemy('zombie',-1.55,-28,3),makeEnemy('witch',.1,-35,4)];
let playerHealth=100,active=false,gameOver=false,remaining=enemies.length,elapsed=0,castCooldown=0,toastTimer=0;
const projectiles=[];const clock=new THREE.Clock();const move={x:0,z:0,sprint:false};const keys={};
const ui={health:document.querySelector('#health-value'),healthFill:document.querySelector('#health-fill'),foes:document.querySelector('#foe-label'),objective:document.querySelector('#objective-text'),toast:document.querySelector('#toast'),intro:document.querySelector('#intro'),victory:document.querySelector('#victory'),defeat:document.querySelector('#defeat'),spellHint:document.querySelector('#spell-hint')};
function notify(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.1;}
function refreshHUD(){ui.health.textContent=playerHealth;ui.healthFill.style.width=playerHealth+'%';ui.healthFill.style.background=playerHealth<35?'linear-gradient(90deg,#9f334a,#f27e73)':'linear-gradient(90deg,#bd5165,#f1b58b)';ui.foes.textContent=remaining===0?'The way is open':' '+remaining+' shadow'+(remaining===1?'':'s')+' remain';}
function makeBolt(origin,target,color,fromEnemy=false){const mat=new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:2.3,roughness:.2});const orb=mesh(new THREE.IcosahedronGeometry(fromEnemy?.14:.18,1),mat,scene,origin.x,origin.y,origin.z);const light=new THREE.PointLight(color,fromEnemy?3:4,3,2);orb.add(light);const dir=target.clone().sub(origin).normalize();projectiles.push({mesh:orb,vel:dir.clone().multiplyScalar(fromEnemy?8.2:17),life:2.4,fromEnemy,target:fromEnemy?null:target});}
function cast(){if(!active||gameOver||castCooldown>0)return;castCooldown=.31;wandGem.material=mats.glow;wandGem.scale.setScalar(1.5);setTimeout(()=>wandGem.scale.setScalar(1),100);let target=null,best=Infinity;for(const e of enemies){if(!e.alive)continue;const d=player.position.distanceTo(e.group.position);if(d<best){best=d;target=e;}}
 const origin=wand.getWorldPosition(new THREE.Vector3()).add(new THREE.Vector3(0,.27,-.28));let destination;if(target){destination=target.group.position.clone().add(new THREE.Vector3(0,1.55,0));}else destination=origin.clone().add(new THREE.Vector3(0,.5,-18));makeBolt(origin,destination,0x9de8ff,false);}
function enemyFire(e){const origin=e.group.position.clone().add(new THREE.Vector3(0,1.8,0));const aim=player.position.clone().add(new THREE.Vector3(0,1.5,0));makeBolt(origin,aim,e.type==='witch'?0xd47dff:0x9edc83,true);e.attackFlash=.18;}
function damagePlayer(amount){playerHealth=Math.max(0,playerHealth-amount);refreshHUD();playerAura.intensity=4;setTimeout(()=>playerAura.intensity=1.4,140);notify('A shadow bolt strikes! −'+amount+' life');if(playerHealth<=0){active=false;gameOver=true;ui.defeat.classList.remove('hidden');}}
function damageEnemy(e,amount){if(!e.alive)return;e.hp=Math.max(0,e.hp-amount);e.fill.scale.x=e.hp/100;e.fill.position.x=-(1-e.hp/100)*.625;e.group.scale.set(1.07,1.07,1.07);setTimeout(()=>{if(e.alive)e.group.scale.set(1,1,1)},100);if(e.hp<=0){e.alive=false;e.group.visible=false;remaining--;refreshHUD();notify(e.type==='witch'?'The witch dissolves into starlight':'The restless dead fall still');if(remaining===0){ui.objective.textContent='The path is clear. Reach the castle';gate.visible=false;notify('The curse is broken. Find Shadowkeep!');}}
}
function createReset(){for(const p of projectiles){scene.remove(p.mesh);}projectiles.length=0;playerHealth=100;remaining=enemies.length;enemies.forEach(e=>{e.hp=100;e.alive=true;e.group.visible=true;e.group.position.set(e.baseX,0,e.baseZ);e.fill.scale.x=1;e.fill.position.x=0;e.shot=1+Math.random()*1.8;});player.position.set(0,0,8);gameOver=false;active=true;castCooldown=0;gate.visible=true;ui.objective.textContent='Find the path through the cursed wood';ui.intro.classList.add('hidden');ui.victory.classList.add('hidden');ui.defeat.classList.add('hidden');refreshHUD();notify('The veil stirs. Your wand is ready.');}

function update(dt){elapsed+=dt;if(!active)return;castCooldown=Math.max(0,castCooldown-dt);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show');}
 let ix=move.x,iz=move.z;if(keys.KeyA||keys.ArrowLeft)ix-=1;if(keys.KeyD||keys.ArrowRight)ix+=1;if(keys.KeyW||keys.ArrowUp)iz-=1;if(keys.KeyS||keys.ArrowDown)iz+=1;const l=Math.hypot(ix,iz);if(l>1){ix/=l;iz/=l;}const speed=(move.sprint||keys.ShiftLeft||keys.ShiftRight?8.2:5.4);player.position.x=THREE.MathUtils.clamp(player.position.x+ix*speed*dt,-2.15,2.15);player.position.z=THREE.MathUtils.clamp(player.position.z+iz*speed*dt,-46,13);player.rotation.y=ix*.2;
 const walking=l>.05;player.position.y=walking?Math.abs(Math.sin(elapsed*10))*.045:Math.sin(elapsed*2)*.018;wand.rotation.z=walking?Math.sin(elapsed*8)*.055:Math.sin(elapsed*2.7)*.035;
 for(const e of enemies){if(!e.alive)continue;e.bar.quaternion.copy(camera.quaternion);e.group.position.x=e.baseX+Math.sin(elapsed*1.1+e.id)*.17;e.group.position.y=Math.sin(elapsed*2+e.id)*.035;if(e.type==='zombie'&&Math.abs(e.group.position.z-player.position.z)<7)e.group.position.x+=Math.sin(elapsed*2.4+e.id)*.025;
 e.shot-=dt;if(e.shot<=0&&player.position.distanceTo(e.group.position)<23){enemyFire(e);e.shot=(e.type==='witch'?2.4:3.3)+Math.random()*1.25;}}
 for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.life-=dt;p.mesh.position.addScaledVector(p.vel,dt);if(p.fromEnemy){if(p.mesh.position.distanceTo(player.position.clone().add(new THREE.Vector3(0,1.3,0)))<.9){scene.remove(p.mesh);projectiles.splice(i,1);damagePlayer(10);continue;}}else{let hit=false;for(const e of enemies){if(!e.alive)continue;const center=e.group.position.clone().add(new THREE.Vector3(0,1.55,0));if(p.mesh.position.distanceTo(center)<.9){damageEnemy(e,10);hit=true;break;}}if(hit){scene.remove(p.mesh);projectiles.splice(i,1);continue;}}
 if(p.life<=0||Math.abs(p.mesh.position.x)>30||p.mesh.position.z<-65||p.mesh.position.z>20){scene.remove(p.mesh);projectiles.splice(i,1);}}
 // Camera follows behind the hero, opening its view as the castle approaches.
 const desired=new THREE.Vector3(player.position.x*.48,5.5,player.position.z+10.2);camera.position.lerp(desired,1-Math.exp(-dt*2.8));const look=new THREE.Vector3(player.position.x*.32,1.75,player.position.z-7.5);camera.lookAt(look);
 if(remaining===0&&player.position.z<-44){active=false;ui.victory.classList.remove('hidden');ui.objective.textContent='Shadowkeep is yours';}
}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04);update(dt);renderer.render(scene,camera);}animate();
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,2));}window.addEventListener('resize',resize);
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space'&&!e.repeat)cast();});window.addEventListener('keyup',e=>{keys[e.code]=false;});canvas.addEventListener('pointerdown',e=>{if(active&&e.button===0)cast();});
document.querySelector('#start-button').addEventListener('click',createReset);document.querySelector('#replay-button').addEventListener('click',createReset);document.querySelector('#retry-button').addEventListener('click',createReset);document.querySelector('#cast-button').addEventListener('pointerdown',e=>{e.preventDefault();cast();});
// Accessible virtual joystick, bounded to its base and safe-area-aware layout.
const joystick=document.querySelector('#joystick'),knob=document.querySelector('#joy-knob');let joyPointer=null;joystick.addEventListener('pointerdown',e=>{e.preventDefault();joyPointer=e.pointerId;joystick.setPointerCapture(joyPointer);setStick(e);});joystick.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)setStick(e);});function releaseStick(e){if(e.pointerId!==joyPointer)return;joyPointer=null;move.x=0;move.z=0;knob.style.transform='translate(-50%,-50%)';}joystick.addEventListener('pointerup',releaseStick);joystick.addEventListener('pointercancel',releaseStick);function setStick(e){const r=joystick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=r.width*.31,len=Math.hypot(dx,dy),scale=len>max?max/len:1;const x=dx*scale,y=dy*scale;knob.style.transform=`translate(calc(-50% + ${x}px),calc(-50% + ${y}px))`;move.x=x/max;move.z=y/max;}
refreshHUD();

