function update(dt){elapsed+=dt;if(!active)return;castCooldown=Math.max(0,castCooldown-dt);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show');}
 let ix=move.x,iz=move.z;if(keys.KeyA||keys.ArrowLeft)ix-=1;if(keys.KeyD||keys.ArrowRight)ix+=1;if(keys.KeyW||keys.ArrowUp)iz-=1;if(keys.KeyS||keys.ArrowDown)iz+=1;const l=Math.hypot(ix,iz);if(l>1){ix/=l;iz/=l;}const speed=(move.sprint||keys.ShiftLeft||keys.ShiftRight?8.2:5.4);player.position.x=THREE.MathUtils.clamp(player.position.x+ix*speed*dt,-2.15,2.15);player.position.z=THREE.MathUtils.clamp(player.position.z+iz*speed*dt,-46,13);player.rotation.y=ix*.2;
 const walking=l>.05;player.position.y=walking?Math.abs(Math.sin(elapsed*10))*.045:Math.sin(elapsed*2)*.018;wand.rotation.z=walking?Math.sin(elapsed*8)*.055:Math.sin(elapsed*2.7)*.035;
 for(const e of enemies){if(!e.alive)continue;e.bar.quaternion.copy(camera.quaternion);e.group.position.x=e.baseX+Math.sin(elapsed*1.1+e.id)*.17;e.group.position.y=Math.sin(elapsed*2+e.id)*.035;if(e.type==='zombie'&&Math.abs(e.group.position.z-player.position.z)<7)e.group.position.x+=Math.sin(elapsed*2.4+e.id)*.025;e.shot-=dt;if(e.shot<=0&&player.position.distanceTo(e.group.position)<23){enemyFire(e);e.shot=(e.type==='witch'?2.4:3.3)+Math.random()*1.25;}}
 for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.life-=dt;p.mesh.position.addScaledVector(p.vel,dt);if(p.fromEnemy){if(p.mesh.position.distanceTo(player.position.clone().add(new THREE.Vector3(0,1.3,0)))<.9){scene.remove(p.mesh);projectiles.splice(i,1);damagePlayer(10);continue;}}else{let hit=false;for(const e of enemies){if(!e.alive)continue;const center=e.group.position.clone().add(new THREE.Vector3(0,1.55,0));if(p.mesh.position.distanceTo(center)<.9){damageEnemy(e,10);hit=true;break;}}if(hit){scene.remove(p.mesh);projectiles.splice(i,1);continue;}}if(p.life<=0||Math.abs(p.mesh.position.x)>30||p.mesh.position.z<-65||p.mesh.position.z>20){scene.remove(p.mesh);projectiles.splice(i,1);}}
 const desired=new THREE.Vector3(player.position.x*.48,5.5,player.position.z+10.2);camera.position.lerp(desired,1-Math.exp(-dt*2.8));const look=new THREE.Vector3(player.position.x*.32,1.75,player.position.z-7.5);camera.lookAt(look);if(remaining===0&&player.position.z<-44){active=false;ui.victory.classList.remove('hidden');ui.objective.textContent='Shadowkeep is yours';}}
