import { startForCapture } from './capture-start.mjs'
import captures from './wip-screenshots.cjs'
import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
captures.instrument({ chromium })
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const url = process.env.CAPTURE_URL, output = process.env.CAPTURE_DIR
if (!url || !output) throw new Error('Set CAPTURE_URL and CAPTURE_DIR.')
mkdirSync(output, { recursive: true })
const transient = error => { throw Object.assign(error, { exitCode: 75 }) }
let browser
try {
  browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 }).catch(transient)
  for (const [name, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
    const page = await browser.newPage({ viewport: { width, height } }).catch(transient)
    page.setDefaultTimeout(30000)
    const failures = []
    page.on('pageerror', error => { console.error(error.message); failures.push(error.message) })
    page.on('response', response => { if (response.status() >= 400 && new URL(response.url()).origin === new URL(url).origin) failures.push(`HTTP ${response.status()}: ${response.url()}`) })
    const response = await page.goto(url, { waitUntil: 'load', timeout: 45000 }).catch(transient)
    if (!response?.ok()) throw Object.assign(new Error(`HTTP ${response?.status()} loading preview`), { exitCode: !response || [408, 429, 500, 502, 503, 504].includes(response.status()) ? 75 : 1 })
    await page.locator(process.env.CAPTURE_READY_SELECTOR || 'body').waitFor({ state: 'visible' })
    await page.waitForFunction(() => document.fonts.status === 'loaded')
    const start = await startForCapture(page, {
      enabled: process.env.CAPTURE_AUTO_START !== 'false',
      selector: process.env.CAPTURE_START_SELECTOR || ''
    })
    console.log(`Capture ${name}: auto-start ${start.clicked ? 'clicked' : start.reason}`)
    await page.waitForTimeout(1000)
    await page.screenshot({ path: join(output, `final-${name}.png`), timeout: 30000 }).catch(error => {
      if (error.name === 'TimeoutError' || !browser.isConnected()) transient(error)
      throw error
    })
    if (process.env.CAPTURE_STRICT === '1' && failures.length) throw new Error(`Published build failed: ${failures.join('; ')}`)
    await page.close()
  }
} catch (error) { console.error(error); process.exitCode = error.exitCode || 1 }
finally { await browser?.close().catch(error => { console.error(error); process.exitCode ||= 75 }) }

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.166.1/build/three.module.js';
const canvas=document.querySelector('#scene'),renderer=new THREE.WebGLRenderer({canvas,antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio||1,2));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x171326);scene.fog=new THREE.FogExp2(0x171326,.023);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,180);scene.add(new THREE.HemisphereLight(0xb7a3d8,0x21182c,2.1));const moon=new THREE.DirectionalLight(0xe4d6ff,2.1);moon.position.set(-12,20,8);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);moon.shadow.camera.left=-28;moon.shadow.camera.right=28;moon.shadow.camera.top=30;moon.shadow.camera.bottom=-30;scene.add(moon);const warm=new THREE.PointLight(0xffbb75,28,30,2);warm.position.set(1,5,-23);scene.add(warm);
const ground=new THREE.Mesh(new THREE.PlaneGeometry(120,150),new THREE.MeshStandardMaterial({color:0x272233,roughness:.96}));ground.rotation.x=-Math.PI/2;ground.position.set(0,-.12,-26);ground.receiveShadow=true;scene.add(ground);
const pathMat=new THREE.MeshStandardMaterial({color:0x51485b,roughness:.85});for(let i=0;i<33;i++){const m=new THREE.Mesh(new THREE.BoxGeometry(5.3,.14,2.05),pathMat);m.position.set(0,-.02,13-i*2.15);m.receiveShadow=true;m.castShadow=true;scene.add(m);}const edgeMat=new THREE.MeshStandardMaterial({color:0x463c4d,roughness:1});for(const x of [-3.15,3.15]){const m=new THREE.Mesh(new THREE.BoxGeometry(.2,.3,73),edgeMat);m.position.set(x,.04,-23);m.receiveShadow=true;scene.add(m);}
const mats={bark:new THREE.MeshStandardMaterial({color:0x282132,roughness:1}),leaf:new THREE.MeshStandardMaterial({color:0x2d293b,roughness:1}),leaf2:new THREE.MeshStandardMaterial({color:0x40344b,roughness:1}),gold:new THREE.MeshStandardMaterial({color:0xd9b96f,metalness:.55,roughness:.35,emissive:0x69441a,emissiveIntensity:.3}),stone:new THREE.MeshStandardMaterial({color:0x51465d,roughness:.85}),castle:new THREE.MeshStandardMaterial({color:0x494257,roughness:.85}),roof:new THREE.MeshStandardMaterial({color:0x292335,roughness:.82}),glow:new THREE.MeshStandardMaterial({color:0xffd789,emissive:0xffa832,emissiveIntensity:2.6}),cloak:new THREE.MeshStandardMaterial({color:0x252a3c,roughness:.9}),skin:new THREE.MeshStandardMaterial({color:0xd4aa83,roughness:.75}),witch:new THREE.MeshStandardMaterial({color:0x49405c,roughness:.8}),zombie:new THREE.MeshStandardMaterial({color:0x59665a,roughness:1}),dark:new THREE.MeshStandardMaterial({color:0x2c2634,roughness:.9})};
function mesh(geo,mat,parent,x=0,y=0,z=0){const m=new THREE.Mesh(geo,mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function addTree(x,z,scale=1,variant=0){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(scale);scene.add(g);mesh(new THREE.CylinderGeometry(.24,.48,5,7),mats.bark,g,0,2.5,0);for(let i=0;i<3;i++){const c=mesh(new THREE.ConeGeometry(1.6-i*.25,3.3,7),i%2?mats.leaf:mats.leaf2,g,0,4.2+i*1.25,0);c.rotation.y=variant*.8+i;}for(let b=0;b<2;b++){const m=mesh(new THREE.CylinderGeometry(.09,.17,2.3,6),mats.bark,g,b?-.8:.8,3.4,b?-.4:.35);m.rotation.z=b?-.68:.68;m.rotation.x=b?.15:-.2;}}
