 await page.screenshot({path:'screenshots/latest.jpg',type:'jpeg',quality:62});
 console.log(JSON.stringify({http:response.status(),desktop:state},null,2));
 const mobile=await browser.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true});
 mobile.on('pageerror',e=>failures.push('mobile pageerror: '+e.message));
 await mobile.goto('http://localhost:3002',{waitUntil:'load',timeout:45000});
