 const mobileState=await mobile.evaluate(()=>({controlsVisible:getComputedStyle(document.querySelector('#mobile-controls')).display!=='none',startButton:!!document.querySelector('#start-button')}));
 await mobile.locator('#start-button').click();
 await mobile.locator('#cast-button').dispatchEvent('pointerdown',{pointerId:1,pointerType:'touch',button:0});
 await mobile.waitForTimeout(700);
 console.log(JSON.stringify({mobile:mobileState,failures},null,2));
 if(failures.length) process.exitCode=1;
 await mobile.close();
} finally { await browser.close(); }
