import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const rt=join(process.env.HOME,'.local/share/omgithub-playwright');
const require=createRequire(join(rt,'package.json'));
const {chromium}=require('playwright');
const cfg=JSON.parse(readFileSync(join(rt,'linux.json'),'utf8'));
process.env.DISPLAY||=':'+readFileSync(join(rt,'display'),'utf8').trim();
const browser=await chromium.launch({...cfg.browser.launchOptions});
const errors=[];
try {
 const page=await browser.newPage({viewport:{width:1120,height:700}});
 page.on('pageerror',e=>errors.push('pageerror: '+e.message));
 page.on('console',m=>{if(m.type()==='error')errors.push('console: '+m.text())});
 page.on('response',r=>{if(r.status()>=400)errors.push(`HTTP ${r.status()}: ${r.url()}`)});
 const response=await page.goto('http://localhost:3002',{waitUntil:'load',timeout:45000});
 await page.evaluate(()=>{window.__frames=0; const count=()=>{window.__frames++;requestAnimationFrame(count)};requestAnimationFrame(count)});
 await page.evaluate(()=>document.fonts.ready);
 await page.locator('#start-button').click();
 await page.waitForTimeout(3000);
 const desktop=await page.evaluate(()=>({introHidden:document.querySelector('#intro').classList.contains('hidden'),health:document.querySelector('#health-value').textContent,foes:document.querySelector('#foe-label').textContent,objective:document.querySelector('#objective-text').textContent,webgl:!!document.querySelector('#scene').getContext('webgl2'),frames:window.__frames,toastClass:document.querySelector('#toast').className}));
 mkdirSync('screenshots',{recursive:true});
 await page.screenshot({path:'screenshots/latest.jpg',type:'jpeg',quality:62});
 const mobile=await browser.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true});
 mobile.on('pageerror',e=>errors.push('mobile pageerror: '+e.message));
 mobile.on('console',m=>{if(m.type()==='error')errors.push('mobile console: '+m.text())});
 mobile.on('response',r=>{if(r.status()>=400)errors.push(`mobile HTTP ${r.status()}: ${r.url()}`)});
 await mobile.goto('http://localhost:3002',{waitUntil:'load',timeout:45000});
 await mobile.evaluate(()=>document.fonts.ready);
 const controlsVisible=await mobile.locator('#mobile-controls').isVisible();
 await mobile.locator('#start-button').click();
 await mobile.locator('#cast-button').dispatchEvent('pointerdown',{pointerId:1,pointerType:'touch',button:0});
 await mobile.waitForTimeout(450);
 console.log(JSON.stringify({http:response.status(),desktop,mobile:{controlsVisible,started:await mobile.locator('#intro').evaluate(e=>e.classList.contains('hidden'))},errors},null,2));
 if(errors.length)process.exitCode=1;
 await mobile.close();
} finally {await browser.close()}
EOF

