try{
 const page=await browser.newPage({viewport:{width:1120,height:700}});page.on('pageerror',e=>errors.push('desktop: '+e.message));page.on('console',m=>{if(m.type()==='error')errors.push('desktop console: '+m.text())});page.on('response',r=>{if(r.status()>=400)errors.push(`HTTP ${r.status()} ${r.url()}`)});const response=await page.goto('http://localhost:3002',{waitUntil:'load',timeout:45000});await page.evaluate(()=>document.fonts.ready);await page.locator('#start-button').click();await page.waitForTimeout(10000);await page.addStyleTag({content:'#toast{opacity:0!important}'});const desktop=await page.evaluate(()=>({introHidden:document.querySelector('#intro').classList.contains('hidden'),health:document.querySelector('#health-value').textContent,foes:document.querySelector('#foe-label').textContent,objective:document.querySelector('#objective-text').textContent,webgl:!!document.querySelector('#scene').getContext('webgl2')}));mkdirSync('screenshots',{recursive:true});await page.screenshot({path:'screenshots/latest.jpg',type:'jpeg',quality:60});
 const mobile=await browser.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true});mobile.on('pageerror',e=>errors.push('mobile: '+e.message));mobile.on('console',m=>{if(m.type()==='error')errors.push('mobile console: '+m.text())});mobile.on('response',r=>{if(r.status()>=400)errors.push(`mobile HTTP ${r.status()} ${r.url()}`)});await mobile.goto('http://localhost:3002',{waitUntil:'load',timeout:45000});const controlsVisible=await mobile.locator('#mobile-controls').isVisible();await mobile.locator('#start-button').click();const joystick=mobile.locator('#joystick');const box=await joystick.boundingBox();await mobile.mouse.move(box.x+box.width/2,box.y+box.height/2);await mobile.mouse.down();await mobile.mouse.move(box.x+box.width*.72,box.y+box.height/2,{steps:2});await mobile.mouse.up();await mobile.locator('#cast-button').dispatchEvent('pointerdown',{pointerId:1,pointerType:'touch',button:0});await mobile.waitForTimeout(500);console.log(JSON.stringify({http:response.status(),desktop,mobile:{controlsVisible,started:await mobile.locator('#intro').evaluate(e=>e.classList.contains('hidden'))},errors},null,2));if(errors.length)process.exitCode=1;await mobile.close();
